// excellent hash function for computer graphics
uvec4 pcg4d(uvec4 v) {
    // https://www.jcgt.org/published/0009/03/02/
    v = v * 0x0019660Du + 0x3C6EF35Fu;
    v.x += v.y*v.w; v.y += v.z*v.x; v.z += v.x*v.y; v.w += v.y*v.z;
    v ^= v >> 16u;
    v.x += v.y*v.w; v.y += v.z*v.x; v.z += v.x*v.y; v.w += v.y*v.z;
    return v;
}

// shader entrypoint
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    fragColor = vec4(0); // initial output

    uvec4 state = uvec4(fragCoord.x, fragCoord.y, iFrame, 0) + 1u; // initial RNG state

    for(int i = 0; i < 2048; i++) {
        state = pcg4d(state); // update RNG state

        fragColor += (1.0/2048.0)*2.32830629776081821092e-10*vec4(state); // accumulate random value
    }

    fragColor.rgb = 16.0*(fragColor.rgb-0.5)+0.5; // increase contrast

    fragColor.a = 1.0; // set alpha to 1
}
